def value_iteration(states, actions, P, R, gamma, theta=1e-6):
    V = {s: 0.0 for s in states}
    while True:
        delta = 0.0
        for s in states:
            v_old = V[s]
            V[s] = max(
                sum(P[s][a][s2] * (R[s][a][s2] + gamma * V[s2])
                    for s2 in states)
                for a in actions)
            delta = max(delta, abs(v_old - V[s]))
        if delta < theta:
            return V

# one synchronous sweep over a deterministic gridworld
def sweep(V, cells, goal, step_reward, gamma):
    newV = dict(V)
    for s in cells:
        if s == goal:
            continue
        best = max(step_reward + gamma * V[nxt(s, a)]
                   for a in ('U','D','L','R'))
        newV[s] = best
    return newV
